import{_ as s,C as o,o as t,c as l,a2 as a,b as r,w as i,a as d,E as c,a3 as p}from"./chunks/framework.CZqXuAiL.js";const y=JSON.parse('{"title":"Panel Firewall","description":"Host-level firewall and DDoS mitigation for the Pterodactyl Panel host itself — L3/L4 iptables protection, adaptive EWMA mitigation, and L7 access-log HTTP-flood detection behind an admin-only panel UI.","frontmatter":{"title":"Panel Firewall","description":"Host-level firewall and DDoS mitigation for the Pterodactyl Panel host itself — L3/L4 iptables protection, adaptive EWMA mitigation, and L7 access-log HTTP-flood detection behind an admin-only panel UI."},"headers":[],"relativePath":"panel-firewall/index.md","filePath":"panel-firewall/index.md","lastUpdated":1785522036000}'),h={name:"panel-firewall/index.md"};function u(g,e,m,f,b,k){const n=o("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a('<h1 id="panel-firewall" tabindex="-1">Panel Firewall <a class="header-anchor" href="#panel-firewall" aria-label="Permalink to &quot;Panel Firewall&quot;">​</a></h1><p><strong>Host-level firewall &amp; DDoS mitigation for the Pterodactyl Panel host itself</strong> — panel pages, API, websocket, and SFTP traffic terminating on the panel machine — driven by an admin-only panel UI that talks to a privileged, HMAC-authenticated Node.js daemon.</p><p>Panel Firewall protects the machine your panel runs on, not the game servers. It programs kernel iptables/ipset rules through atomic <code>iptables-restore</code> transactions with checkpoints, a 60-second confirm/auto-rollback window, and an emergency safe mode — so a bad apply can never lock you out. On top of the static L3/L4 ruleset, a SMART engine watches traffic with EWMA anomaly detection and escalates through L1→L3 mitigations automatically, while an L7 sensor tails the web server&#39;s access log and temporarily bans HTTP-flood sources — with <strong>no nginx/apache config changes required</strong>.</p><div class="tip custom-block" style="margin-top:1.5rem;"><p><strong>Built for PingLess Studios by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer">AnAverageBeing</a></strong><a href="https://github.com/AnAverageBeing/pterodactyl-panel-firewall" target="_blank" rel="noreferrer">GitHub Repo</a> · <a href="https://studio.pingless.org" target="_blank" rel="noreferrer">Studio</a></p></div><div class="info custom-block"><p class="custom-block-title">Panel host vs. per-server protection</p><p>Panel Firewall guards the <strong>panel host only</strong>. For per-game-server container firewalling, see the sibling project <a href="/pingless-studios-docs/firewall-plus/">Firewall-Plus</a>.</p></div><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',7)),(t(),r(p,null,{default:i(()=>[c(n,{id:"mermaid-23",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20Panel%5BPterodactyl%20Panel%20-%20admin%20only%5D%0A%20%20%20%20%20%20%20%20UI%5BPanel%20Firewall%20Admin%20UI%5D%20--%3E%20SVC%5BDaemonClient%20%2B%20ConfigBuilder%5D%0A%20%20%20%20%20%20%20%20SVC%20--%3E%20DB%5B(Panel%20DB%20-%20settings%2C%20lists%2C%20audit%2C%20encrypted%20token)%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Host%5BPanel%20Host%5D%0A%20%20%20%20%20%20%20%20SVC%20--%3E%7CHMAC-SHA256%20signed%20JSON%3Cbr%2F%3EBearer%20token%20%2B%20IP%20allowlist%7C%20API%5BDaemon%20API%20127.0.0.1%3A8475%5D%0A%20%20%20%20%20%20%20%20subgraph%20Daemon%5Bpanel-firewall%20daemon%20-%20Node.js%2C%20root%2C%20systemd%20sandbox%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20API%20--%3E%20TX%5BTransaction%20Engine%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20TX%20--%3E%20CP%5BCheckpoint%20Manager%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20TX%20--%3E%20BE%5BIptables%20Backend%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20SMART%5BSMART%20EWMA%20Monitor%5D%20--%3E%20MIT%5BL1-L3%20Mitigations%20%2B%20Temp%20Bans%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20L7%5BL7%20Access-Log%20Sensor%5D%20--%3E%20MIT%0A%20%20%20%20%20%20%20%20%20%20%20%20BE%20--%3E%20KERNEL%5Biptables-restore%20%2B%20ipset%5D%0A%20%20%20%20%20%20%20%20%20%20%20%20MIT%20--%3E%20KERNEL%0A%20%20%20%20%20%20%20%20%20%20%20%20TX%20--%3E%20SQLITE%5B(SQLite%20state%20-%20ownership%2C%20audit%2C%20bans%2C%20analytics)%5D%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20%20%20%20%20KERNEL%20--%3E%20NFT%5BKernel%20netfilter%20-%20PTDL_*%20chains%20only%5D%0A%20%20%20%20end%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>The <strong>panel</strong> never calls <code>iptables</code> or <code>ipset</code>. Every mutation is an HMAC-signed JSON request to the <strong>daemon</strong>, a Fastify + better-sqlite3 service on <code>127.0.0.1:8475</code> running as root under a sandboxed systemd unit (<code>CAP_NET_ADMIN</code>/<code>CAP_NET_RAW</code> only). The daemon is the single privileged component and refuses to touch any chain, rule, or ipset outside its reserved <code>PTDL_*</code> / <code>ptdl-*</code> ownership prefixes.</p><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>L3/L4 packet hygiene &amp; rate limiting</strong> — invalid/fragment/null-scan/XMAS/NEW-non-SYN drops, per-IP NEW-connection and SYN hashlimits, whitelist-first rule order with a final <code>RETURN</code> safety rail. See <a href="./architecture/protection-layers">Protection Layers</a>.</li><li><strong>5 traffic presets</strong> — <code>low</code>, <code>medium</code>, <code>high</code>, <code>veryHigh</code>, <code>underAttack</code>, tuning PPS/CPS/SYN/burst/concurrency ceilings per deployment.</li><li><strong>Whitelist &amp; blacklist ipsets</strong> — <code>hash:net</code> sets with strict CIDR validation, O(1) kernel lookup, and temp-ban automation with expiry.</li><li><strong>SMART adaptive mitigation</strong> — EWMA + variance anomaly detection (default 4σ) driving L1→L3 mitigation levels with cooldowns and repeat-offender scoring.</li><li><strong>L7 HTTP-flood detection</strong> — tails nginx/apache/caddy access logs (autodetected), counts per-IP request rates in a sliding window, and feeds offenders into the temp-ban ipset with a per-minute ban budget. Private/reserved IPs and whitelist entries are never banned.</li><li><strong>Transactional, crash-safe applies</strong> — plan → validate → fsync&#39;d checkpoint → atomic <code>iptables-restore --noflush</code> → verify → 60s confirm window with automatic rollback, plus startup recovery of expired pending applies.</li><li><strong>One-command install</strong> — Blueprint <code>.blueprint</code> or standalone <code>install.sh</code>; the installer auto-installs the daemon and auto-generates the shared bearer token. No manual token step.</li><li><strong>Analytics &amp; audit</strong> — traffic, mitigation and ban timeseries with Chart.js graphs, dual panel+daemon audit logs, Discord-compatible webhooks with HMAC secrets.</li></ul><hr><h2 id="quick-install" tabindex="-1">Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;">​</a></h2><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-NqsZY" id="tab-AcE6qfM" checked><label data-title="Blueprint" for="tab-AcE6qfM">Blueprint</label><input type="radio" name="group-NqsZY" id="tab-KHkYysv"><label data-title="Standalone" for="tab-KHkYysv">Standalone</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pterodactylpanelfirewall-v0.3.0.blueprint</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panel-firewall-standalone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div></div></div><p>Both paths end the same way: files merged, migrations run, daemon installed to <code>/opt/panel-firewall</code>, 64-hex token generated and synced into the panel DB, systemd service running. See <a href="./getting-started/installation">Installation</a> for the full guide and troubleshooting.</p><hr><h2 id="blueprint-vs-standalone" tabindex="-1">Blueprint vs Standalone <a class="header-anchor" href="#blueprint-vs-standalone" aria-label="Permalink to &quot;Blueprint vs Standalone&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Blueprint</th><th>Standalone</th></tr></thead><tbody><tr><td>Requirement</td><td>Blueprint framework installed</td><td>Stock Pterodactyl panel, root shell</td></tr><tr><td>Install command</td><td><code>blueprint -install &lt;file&gt;.blueprint</code></td><td><code>sudo bash install.sh</code></td></tr><tr><td>Daemon auto-install + auto token</td><td>Yes</td><td>Yes</td></tr><tr><td>Provider registration</td><td><code>data/install.sh</code> (hard fail)</td><td><code>data/patch.sh</code> (hard fail)</td></tr><tr><td>Laravel 11 <code>bootstrap/providers.php</code></td><td>Supported</td><td>Supported</td></tr><tr><td>Uninstall</td><td><code>blueprint -remove</code> / <code>data/remove.sh</code></td><td><code>sudo bash uninstall.sh</code></td></tr><tr><td>Data kept on remove</td><td>Yes (unless <code>--purge-data</code>)</td><td>Yes (unless <code>--purge-data</code>)</td></tr></tbody></table><hr><h2 id="documentation-map" tabindex="-1">Documentation Map <a class="header-anchor" href="#documentation-map" aria-label="Permalink to &quot;Documentation Map&quot;">​</a></h2><ul><li><a href="./getting-started/installation">Installation</a> — prerequisites, both install paths, verification, troubleshooting, uninstall</li><li><a href="./configuration/reference">Configuration Reference</a> — every panel setting and daemon <code>config.json</code> key</li><li><a href="./user-guide/api">Daemon API</a> — the HMAC-authenticated REST surface</li><li><a href="./user-guide/webhooks">Webhooks &amp; Alerts</a> — Discord-compatible event notifications</li><li><a href="./architecture/overview">Architecture</a> — components, apply data flow, security model</li><li><a href="./architecture/protection-layers">Protection Layers</a> — L3/L4 ruleset, SMART EWMA, L7 sensor deep dive</li></ul>`,14))])}const A=s(h,[["render",u]]);export{y as __pageData,A as default};
